import sys

def main():
    data = sys.stdin.read().split()
    m, n = int(data[0]), int(data[1])
    adj = [[j for j in range(n) if data[2 + i * n + j] == '1'] for i in range(m)]
    match = [-1] * n

    def try_boy(b, seen):
        for g in adj[b]:
            if not seen[g]:
                seen[g] = True
                if match[g] == -1 or try_boy(match[g], seen):
                    match[g] = b
                    return True
        return False

    res = 0
    for b in range(m):
        if try_boy(b, [False] * n):
            res += 1
    print(res)

