import sys
from functools import lru_cache

data = sys.stdin.read().split()
m, n = int(data[0]), int(data[1])
g = [[int(data[2 + i * n + j]) for j in range(n)] for i in range(m)]

@lru_cache(maxsize=None)
def best(i, used):
    if i == m:
        return 0
    res = best(i + 1, used)
    for j in range(n):
        if g[i][j] and not (used >> j) & 1:
            res = max(res, 1 + best(i + 1, used | (1 << j)))
    return res

print(best(0, 0))

